using System.Security.Claims;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TransPort.Api.Modules.Transporte.DTOs;using TransPort.Api.Modules.Transporte.Repositories;
namespace TransPort.Api.Controllers;
[ApiController,Route("api/transportes"),Authorize(Roles="AdministradorGeneral,Gerente,Empleado,Operativo")]
public sealed class TransportesController(ITransporteRepository repo):ControllerBase
{[HttpGet]public Task<IReadOnlyList<TransporteViajeListadoDto>>Listar(string?estado,string?tipo,int?sedeId,CancellationToken ct)=>repo.ListarAsync(estado,tipo,sedeId,A(),ct);[HttpGet("opciones")]public Task<TransporteOpcionesDto>Opciones(CancellationToken ct)=>repo.OpcionesAsync(A(),ct);[HttpGet("{id:long}")]public async Task<IActionResult>Obtener(long id,CancellationToken ct){var x=await repo.ObtenerAsync(id,A(),ct);return x is null?NotFound():Ok(x);}[HttpPost("vehiculos")]public async Task<IActionResult>Vehiculo(CrearVehiculoTransporteRequest x,CancellationToken ct)=>Ok(new ResultadoTransporteDto(await repo.CrearVehiculoAsync(x,A(),ct)));[HttpPost("conductores")]public async Task<IActionResult>Conductor(CrearConductorTransporteRequest x,CancellationToken ct)=>Ok(new ResultadoTransporteDto(await repo.CrearConductorAsync(x,A(),ct)));[HttpPost]public async Task<IActionResult>Crear(CrearViajeTransporteRequest x,CancellationToken ct)=>Ok(new ResultadoTransporteDto(await repo.CrearViajeAsync(x,A(),ct)));[HttpPut("{id:long}/estado")]public async Task<IActionResult>Estado(long id,EstadoViajeTransporteRequest x,CancellationToken ct)=>await repo.EstadoViajeAsync(id,x,A(),ct)?NoContent():NotFound();[HttpPost("{id:long}/incidencias")]public async Task<IActionResult>Incidencia(long id,CrearIncidenciaTransporteRequest x,CancellationToken ct)=>Ok(new ResultadoTransporteDto(await repo.CrearIncidenciaAsync(id,x,A(),ct)));[HttpPut("incidencias/{id:long}/resolver")]public async Task<IActionResult>Resolver(long id,ResolverIncidenciaTransporteRequest x,CancellationToken ct)=>await repo.ResolverIncidenciaAsync(id,x.Resolucion,A(),ct)?NoContent():NotFound();[HttpDelete("{id:long}"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>Eliminar(long id,CancellationToken ct)=>await repo.EliminarViajeAsync(id,A().UsuarioId,ct)?NoContent():NotFound();[HttpDelete("recursos/{tipo}/{id:int}"),Authorize(Roles="AdministradorGeneral")]public async Task<IActionResult>EliminarRecurso(string tipo,int id,CancellationToken ct)=>await repo.EliminarRecursoAsync(tipo,id,A().UsuarioId,ct)?NoContent():NotFound();private AlcanceTransporte A()=>new(int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!),User.IsInRole("AdministradorGeneral"));}
